export interface ConnectorConfig {
  /** Brevo API key from environment variable BREVO_API_KEY */
  brevoApiKey: string
  /** Numeric Brevo list ID to subscribe the new contact to */
  listId: number
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface HandleResult {
  contactId: number
  email: string
  listId: number
}

function extractEmailAndName(answers: TypeformWebhookPayload['form_response']['answers']): { email: string; name: string } {
  let email = ''
  let name = ''

  for (const answer of answers) {
    if (answer.type === 'email' && answer.email) {
      email = answer.email
    } else if (answer.type === 'text' && answer.text) {
      name = answer.text
    }
  }

  return { email, name }
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  const { brevoApiKey, listId, fetch = globalThis.fetch } = config

  if (!brevoApiKey) {
    throw new Error('Missing required config: brevoApiKey')
  }
  if (!Number.isInteger(listId) || listId <= 0) {
    throw new Error('Missing or invalid required config: listId must be a positive integer')
  }

  const { form_response } = payload
  if (!form_response) {
    throw new Error('Missing required field: form_response')
  }

  const { token, answers } = form_response
  if (!token) {
    throw new Error('Missing required field: form_response.token')
  }
  if (!answers || !Array.isArray(answers)) {
    throw new Error('Missing required field: form_response.answers')
  }

  const { email, name } = extractEmailAndName(answers)
  if (!email) {
    throw new Error('Missing required field: email not found in form_response.answers')
  }
  if (!name) {
    throw new Error('Missing required field: name not found in form_response.answers')
  }

  const body = {
    email,
    attributes: {
      FULLNAME: name
    },
    listIds: [listId]
  }

  const response = await fetch('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Brevo API error: ${response.status} ${response.statusText} for POST https://api.brevo.com/v3/contacts - ${text}`)
  }

  const result = (await response.json()) as { id: number }
  if (!result.id) {
    throw new Error('Brevo API response missing contact id')
  }

  return {
    contactId: result.id,
    email,
    listId
  }
}

